const d = $input.first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const row = (f) => `• <b>${f.recurrence_count}×</b> ${esc(f.workflow_name)} → ${esc(f.failed_node)}: ${esc(f.error_message)} (#${f.id})`;
const weekEnding = $now.setZone('Asia/Kolkata').toISODate();

const text = [
  `<b>📊 Weekly failure digest</b> (7 days to ${weekEnding})`,
  '',
  `New signatures: <b>${d.new_signatures}</b>`,
  `Signatures seen this week: <b>${d.active_signatures}</b>`,
  `Ledger: <b>${d.open_count}</b> open / <b>${d.fixed_count}</b> fixed`,
  '',
  '<b>Top recurring this week</b>',
  ...(d.top_recurring.length ? d.top_recurring.map(row) : ['none 🎉']),
  '',
  '<b>New this week</b>',
  ...(d.new_list.length ? d.new_list.map(row) : ['none']),
].join('\n');

const top = d.top_recurring[0];
return [{ json: {
  text,
  sheet_row: {
    week_ending: weekEnding,
    new_signatures: d.new_signatures,
    active_signatures: d.active_signatures,
    open: d.open_count,
    fixed: d.fixed_count,
    top_signature: top ? `${top.workflow_name} → ${top.failed_node}: ${top.error_message}` : '',
    top_count: top ? top.recurrence_count : 0,
  },
} }];
